import java.util.Scanner;

public class Main {
    public static double computeAbs(double val) {
        return (val < 0) ? -val : val;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int x = sc.nextInt();
        int y = sc.nextInt();
        int n = sc.nextInt();

        int numeratorCandidate = 0;
        int denominatorCandidate = 1;
        double minDifference = 1e15;
        double targetRatio = (double) x / y;

        for (int denom = 1; denom <= n; ++denom) {
            int leftLimit = 0;
            int rightLimit = 1000000000;
            while (rightLimit - leftLimit > 10) {
                int m1 = leftLimit + (rightLimit - leftLimit) / 3;
                int m2 = rightLimit - (rightLimit - leftLimit) / 3;
                double diff1 = computeAbs(targetRatio - (double) m1 / denom);
                double diff2 = computeAbs(targetRatio - (double) m2 / denom);
                if (diff1 > diff2)
                    leftLimit = m1;
                else
                    rightLimit = m2;
            }
            for (int i = leftLimit; i <= rightLimit + 3; ++i) {
                double currentDiff = computeAbs(targetRatio - (double) i / denom);
                if (currentDiff < minDifference - 1e-15) {
                    minDifference = currentDiff;
                    numeratorCandidate = i;
                    denominatorCandidate = denom;
                }
            }
        }
        System.out.println(numeratorCandidate + "/" + denominatorCandidate);
        sc.close();
    }
}
